"""Financial-character variants for matching only; original evidence is never rewritten."""
import re
_VARIANTS={'資':'资','產':'产','總':'总','額':'额','計':'计','貸':'贷','款':'款','撥':'拨','備':'备','蓋':'盖','減':'减','值':'值','準':'准','對':'对','營':'营','業':'业','潤':'润','稅':'税','團':'团','併':'并','銀':'银','幣':'币','萬':'万','億':'亿','歐':'欧','財':'财','務':'务','報':'报','則':'则','國':'国','會':'会','編':'编','製':'制','礎':'础','際':'际','負':'负','債':'债','權':'权','風':'风','險':'险','級':'级','淨':'净','達':'达','華':'华','東':'东','發':'发','豐':'丰','廣':'广','儲':'储','郵':'邮','設':'设','農':'农','擔':'担','與':'与','歸':'归','屬':'属','標':'标','應':'应','範':'范','圍':'围','證':'证','實':'实','現':'现','於':'于','為':'为','綜':'综','續':'续'}
_VARIANTS.update({'經':'经','終':'终','構':'构','動':'动','虧':'亏','損':'损'})

def variants(text):return str(text).translate(str.maketrans(_VARIANTS))
def search_text(text):return re.sub(r'\s+','',variants(text))
